const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  HeadingLevel, AlignmentType, BorderStyle, WidthType, ShadingType,
  PageBreak, LevelFormat, UnderlineType
} = require('docx');
const fs = require('fs');

// ============================================================================
// PALETA DE COLORS — Identitat visual Bitàcola
// ============================================================================
const C = {
  navy:     "0D1B2A",
  blue:     "1B263B",
  steel:    "415A77",
  light:    "778DA9",
  accent:   "FB8500",
  green:    "2D6A4F",
  red:      "C1121F",
  white:    "FFFFFF",
  gray1:    "F8F9FA",
  gray2:    "DEE2E6",
  gray3:    "6C757D",
  black:    "000000",
  // Estat
  exacto:   "0066CC",
  parcial:  "E6A817",
  nou:      "198754",
};

// ============================================================================
// HELPERS
// ============================================================================
const border1 = { style: BorderStyle.SINGLE, size: 1, color: C.gray2 };
const borders  = { top: border1, bottom: border1, left: border1, right: border1 };

function hd1(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_1,
    spacing: { before: 400, after: 200 },
    children: [new TextRun({ text, font: "Arial", size: 36, bold: true, color: C.navy })],
  });
}

function hd2(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_2,
    spacing: { before: 320, after: 160 },
    children: [new TextRun({ text, font: "Arial", size: 28, bold: true, color: C.blue })],
  });
}

function hd3(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_3,
    spacing: { before: 200, after: 100 },
    children: [new TextRun({ text, font: "Arial", size: 24, bold: true, color: C.steel })],
  });
}

function body(text, opts = {}) {
  return new Paragraph({
    spacing: { before: 80, after: 80 },
    children: [new TextRun({
      text,
      font: "Arial",
      size: 22,
      color: opts.color || "222222",
      bold: opts.bold || false,
      italics: opts.italic || false,
    })],
  });
}

function bodyRuns(runs) {
  return new Paragraph({
    spacing: { before: 80, after: 80 },
    children: runs.map(r => new TextRun({
      text: r.text,
      font: "Arial",
      size: 22,
      color: r.color || "222222",
      bold: r.bold || false,
      italics: r.italic || false,
    })),
  });
}

function bullet(text, opts = {}) {
  return new Paragraph({
    numbering: { reference: "bullets", level: opts.level || 0 },
    spacing: { before: 60, after: 60 },
    children: [new TextRun({
      text,
      font: "Arial",
      size: 22,
      color: opts.color || "222222",
      bold: opts.bold || false,
    })],
  });
}

function code(text) {
  return new Paragraph({
    spacing: { before: 60, after: 60 },
    indent: { left: 360 },
    children: [new TextRun({
      text,
      font: "Courier New",
      size: 18,
      color: C.navy,
    })],
  });
}

function sep() {
  return new Paragraph({
    spacing: { before: 200, after: 200 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 4, color: C.steel, space: 1 } },
    children: [new TextRun("")],
  });
}

function pageBreak() {
  return new Paragraph({ children: [new PageBreak()] });
}

function badgePar(label, color) {
  return new Paragraph({
    spacing: { before: 60, after: 60 },
    children: [new TextRun({
      text: `  ${label}  `,
      font: "Arial",
      size: 20,
      bold: true,
      color: C.white,
      highlight: undefined,
      shading: { type: ShadingType.CLEAR, fill: color },
    })],
  });
}

// Taula simple
function simpleTable(headers, rows, colWidths) {
  const totalW = colWidths.reduce((a, b) => a + b, 0);
  const headerRow = new TableRow({
    tableHeader: true,
    children: headers.map((h, i) => new TableCell({
      borders,
      width: { size: colWidths[i], type: WidthType.DXA },
      shading: { fill: C.navy, type: ShadingType.CLEAR },
      margins: { top: 80, bottom: 80, left: 120, right: 120 },
      children: [new Paragraph({
        children: [new TextRun({ text: h, font: "Arial", size: 20, bold: true, color: C.white })]
      })],
    })),
  });

  const dataRows = rows.map((row, ri) => new TableRow({
    children: row.map((cell, ci) => new TableCell({
      borders,
      width: { size: colWidths[ci], type: WidthType.DXA },
      shading: { fill: ri % 2 === 0 ? "F8F9FA" : C.white, type: ShadingType.CLEAR },
      margins: { top: 80, bottom: 80, left: 120, right: 120 },
      children: [new Paragraph({
        children: [new TextRun({
          text: cell.text || cell,
          font: "Arial", size: 20,
          bold: cell.bold || false,
          color: cell.color || "333333",
        })]
      })],
    })),
  }));

  return new Table({
    width: { size: totalW, type: WidthType.DXA },
    columnWidths: colWidths,
    rows: [headerRow, ...dataRows],
  });
}

// Caixa destacada
function infoBox(title, lines, fillColor) {
  const cellContent = [
    new Paragraph({
      spacing: { before: 60, after: 80 },
      children: [new TextRun({ text: title, font: "Arial", size: 22, bold: true, color: C.navy })]
    }),
    ...lines.map(l => new Paragraph({
      spacing: { before: 40, after: 40 },
      children: [new TextRun({ text: l, font: "Arial", size: 20, color: "333333" })]
    })),
  ];
  return new Table({
    width: { size: 9026, type: WidthType.DXA },
    columnWidths: [9026],
    rows: [new TableRow({
      children: [new TableCell({
        borders: {
          top:    { style: BorderStyle.SINGLE, size: 4, color: C.accent },
          bottom: { style: BorderStyle.SINGLE, size: 1, color: C.gray2 },
          left:   { style: BorderStyle.SINGLE, size: 12, color: C.accent },
          right:  { style: BorderStyle.SINGLE, size: 1, color: C.gray2 },
        },
        shading: { fill: fillColor || "FFF8F0", type: ShadingType.CLEAR },
        margins: { top: 120, bottom: 120, left: 200, right: 120 },
        children: cellContent,
      })],
    })],
  });
}

// ============================================================================
// DIAGRAMA DE FLUX com a taula ASCII visual
// ============================================================================
function fluxRow(label, desc, color) {
  return new TableRow({
    children: [
      new TableCell({
        borders,
        width: { size: 2200, type: WidthType.DXA },
        shading: { fill: color, type: ShadingType.CLEAR },
        margins: { top: 100, bottom: 100, left: 140, right: 140 },
        children: [new Paragraph({
          alignment: AlignmentType.CENTER,
          children: [new TextRun({ text: label, font: "Arial", size: 20, bold: true, color: C.white })]
        })],
      }),
      new TableCell({
        borders,
        width: { size: 6826, type: WidthType.DXA },
        shading: { fill: "FAFAFA", type: ShadingType.CLEAR },
        margins: { top: 100, bottom: 100, left: 140, right: 140 },
        children: [new Paragraph({
          children: [new TextRun({ text: desc, font: "Arial", size: 20, color: "333333" })]
        })],
      }),
    ],
  });
}

function arrowRow() {
  return new TableRow({
    children: [
      new TableCell({
        borders: { top: border1, bottom: border1, left: { style: BorderStyle.NONE }, right: { style: BorderStyle.NONE } },
        width: { size: 2200, type: WidthType.DXA },
        shading: { fill: C.white, type: ShadingType.CLEAR },
        margins: { top: 20, bottom: 20, left: 140, right: 140 },
        children: [new Paragraph({
          alignment: AlignmentType.CENTER,
          children: [new TextRun({ text: "▼", font: "Arial", size: 24, color: C.steel })]
        })],
      }),
      new TableCell({
        borders: { top: border1, bottom: border1, left: { style: BorderStyle.NONE }, right: { style: BorderStyle.NONE } },
        width: { size: 6826, type: WidthType.DXA },
        shading: { fill: C.white, type: ShadingType.CLEAR },
        margins: { top: 20, bottom: 20, left: 140, right: 140 },
        children: [new Paragraph({ children: [new TextRun("")] })],
      }),
    ],
  });
}

function fluxDiagram(title, steps, colors) {
  const rows = [];
  steps.forEach((s, i) => {
    rows.push(fluxRow(s[0], s[1], colors[i % colors.length]));
    if (i < steps.length - 1) rows.push(arrowRow());
  });
  return new Table({
    width: { size: 9026, type: WidthType.DXA },
    columnWidths: [2200, 6826],
    rows,
  });
}

// ============================================================================
// DOCUMENT
// ============================================================================
const doc = new Document({
  styles: {
    default: {
      document: { run: { font: "Arial", size: 22, color: "222222" } }
    },
    paragraphStyles: [
      {
        id: "Heading1", name: "Heading 1", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 36, bold: true, font: "Arial", color: C.navy },
        paragraph: { spacing: { before: 400, after: 200 }, outlineLevel: 0 },
      },
      {
        id: "Heading2", name: "Heading 2", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 28, bold: true, font: "Arial", color: C.blue },
        paragraph: { spacing: { before: 320, after: 160 }, outlineLevel: 1 },
      },
      {
        id: "Heading3", name: "Heading 3", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 24, bold: true, font: "Arial", color: C.steel },
        paragraph: { spacing: { before: 200, after: 100 }, outlineLevel: 2 },
      },
    ],
  },
  numbering: {
    config: [
      {
        reference: "bullets",
        levels: [
          {
            level: 0, format: LevelFormat.BULLET, text: "\u2022",
            alignment: AlignmentType.LEFT,
            style: { paragraph: { indent: { left: 720, hanging: 360 } } },
          },
          {
            level: 1, format: LevelFormat.BULLET, text: "\u25E6",
            alignment: AlignmentType.LEFT,
            style: { paragraph: { indent: { left: 1080, hanging: 360 } } },
          },
        ],
      },
      {
        reference: "numbers",
        levels: [{
          level: 0, format: LevelFormat.DECIMAL, text: "%1.",
          alignment: AlignmentType.LEFT,
          style: { paragraph: { indent: { left: 720, hanging: 360 } } },
        }],
      },
    ],
  },
  sections: [{
    properties: {
      page: {
        size: { width: 11906, height: 16838 },
        margin: { top: 1134, right: 1134, bottom: 1134, left: 1134 },
      },
    },
    children: [

      // =====================================================================
      // PORTADA
      // =====================================================================
      new Paragraph({
        spacing: { before: 1200, after: 200 },
        alignment: AlignmentType.CENTER,
        children: [new TextRun({ text: "BITÀCOLA 1009", font: "Arial", size: 64, bold: true, color: C.navy })],
      }),
      new Paragraph({
        spacing: { before: 0, after: 200 },
        alignment: AlignmentType.CENTER,
        children: [new TextRun({ text: "Sistema Intel\u00B7ligent de Redacci\u00F3 Policial", font: "Arial", size: 32, color: C.steel, italics: true })],
      }),
      new Paragraph({
        spacing: { before: 0, after: 600 },
        alignment: AlignmentType.CENTER,
        border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: C.accent, space: 2 } },
        children: [new TextRun({ text: "DOCUMENTACI\u00D3 T\u00C8CNICA DEL PROJECTE", font: "Arial", size: 22, bold: true, color: C.accent })],
      }),

      simpleTable(
        ["Camp", "Valor"],
        [
          [{ text: "Versi\u00F3", bold: true }, "v4.1  (Març 2026)"],
          [{ text: "Autor", bold: true }, "Agent 1009 — Juan Pablo"],
          [{ text: "Inici del projecte", bold: true }, "Desembre 2024"],
          [{ text: "Estat", bold: true }, { text: "OPERATIU — Beta restringida", bold: true, color: C.green }],
          [{ text: "Desplegament", bold: true }, "Render.com (Free tier) — GitHub Pages"],
          [{ text: "IA principal", bold: true }, "Anthropic Claude (Haiku / Sonnet)"],
          [{ text: "IA vectorial penal", bold: true }, "OpenAI Embeddings + GPT-4o-mini"],
        ],
        [3000, 6026]
      ),

      new Paragraph({ spacing: { before: 600, after: 200 }, children: [new TextRun("")] }),

      // Descripció breu portada
      infoBox(
        "Resum Executiu",
        [
          "Bitàcola és un sistema modular dissenyat per a la Guàrdia Municipal de Catalunya que transforma",
          "text policial col·loquial (dictat per veu o escrit) en informes tècnics DRAG professionals.",
          "Integra verificació automàtica contra bases de dades, anàlisi penal per vectors de comportament",
          "i redacció assistida per IA. El projecte va nàixer al desembre de 2024 i ha evolucionat de manera",
          "progressiva fins a la versió operativa actual.",
        ],
        "EBF5FB"
      ),

      pageBreak(),

      // =====================================================================
      // 1. ARQUITECTURA GENERAL
      // =====================================================================
      hd1("1. Arquitectura General del Sistema"),
      sep(),
      body("El sistema es compon de tres serveis independents que es comuniquen via HTTP/REST. Aquesta separació permet actualitzar cada mòdul de manera independent i desplegar-los en infraestructures diferenciades."),
      new Paragraph({ spacing: { before: 200, after: 100 }, children: [new TextRun("")] }),

      simpleTable(
        ["Servei", "Tecnologia", "URL Render", "Responsabilitat"],
        [
          [{ text: "Frontend", bold: true }, "HTML / JS", "GitHub Pages", "Interfície d'usuari, gestió de sessió, exposició de resultats"],
          [{ text: "Bitàcola Backend", bold: true }, "Node.js + Express", "bitacola-backend.onrender.com", "Proxy segur, autenticació, gestió de sessions, keepalive"],
          [{ text: "Sherlock (API)", bold: true }, "Python FastAPI", "sherlock-backend.onrender.com", "Extracció d'entitats, matching BD, redacció DRAG via Claude"],
          [{ text: "Penal Backend", bold: true }, "Python FastAPI", "penal-backend.onrender.com", "Anàlisi penal per vectors de comportament cosinus"],
        ],
        [1800, 1600, 2800, 2826]
      ),

      new Paragraph({ spacing: { before: 200, after: 100 }, children: [new TextRun("")] }),
      hd2("1.1 Principi de Modularitat"),
      body("Cada servei té una responsabilitat única i ben delimitada. Els serveis no saben res els uns dels altres; es comuniquen únicament a través de contractes d'API JSON definits. Això significa que, per exemple, el mòdul penal pot ser substituït, millorat o migrat a un servidor privat sense afectar la resta del sistema."),
      bullet("Frontend: no conté lògica de negoci, només presentació i gestió de l'estat de la sessió."),
      bullet("Bitàcola Backend: no sap res de redacció ni d'entitats; únicament valida tokens i fa proxy a Sherlock."),
      bullet("Sherlock: no sap res de la interfície ni de sessions; rep un text i retorna un anàlisi complet."),
      bullet("Penal Backend: completament autònom; rep un text i retorna un ranking de possibles infraccions penals."),

      pageBreak(),

      // =====================================================================
      // 2. FLUX PRINCIPAL (3 VARIANTS)
      // =====================================================================
      hd1("2. Diagrama de Flux del Sistema"),
      sep(),
      body("El flux de processament d'un text policial es pot descriure en tres variants principals, depenent del canal d'entrada i del mode de sortida seleccionat."),

      new Paragraph({ spacing: { before: 200 }, children: [new TextRun("")] }),

      // --- VARIANT 1 ---
      hd2("Variant A — Flux Complet (Mode Informe DRAG)"),

      fluxDiagram(
        "flux_a",
        [
          ["AGENT",         "L'agent escriu o dicta el text col·loquial ('han parat un golf negre a Ribes 88 amb dos tíos que portaven droga')"],
          ["FRONTEND",      "Envia el text al Bitàcola Backend amb el token de sessió i el mode seleccionat (parte / informe)"],
          ["BACKEND NODE",  "Valida la sessió, afegeix agent_id i fa proxy al Sherlock API /api/v1/process"],
          ["PAS 1 — REGEX", "Sherlock capitalitza el text i extreu entitats per regex: matrícules (\\d{4}[A-Z]{3}), DNIs, noms propis, adreces"],
          ["PAS 2 — MATCH", "MatcherService cerca cada entitat a hermano_mayor.db: EXACTO (vehicle/DNI) o PARCIAL (persona per tokens) o NOU"],
          ["PAS 3 — MARK",  "Injecta marcadors protegits al text: [[VEHICLE:9915GBN|VW Golf|EXACTO]] [[PERSONA:Juan|...|PARCIAL]]"],
          ["PAS 4 — DRAG",  "Claude (Haiku) redacta l'informe DRAG professional en català respectant els marcadors exactes"],
          ["PAS 5 — RESID", "Extreu entitats residuals del DRAG (les que Claude hagi afegit) i les contrasta novament"],
          ["PAS 6 — ANNOT", "AnnotatorService llegeix marcadors [[...]] → genera text NET + spans de color per al frontend"],
          ["FRONTEND",      "Rep: text DRAG net (editor), anotacions de color (BD), i activa la crida paral·lela al Penal Backend"],
          ["PENAL",         "Simultàniament: el frontend envia el text ORIGINAL al Penal Backend per a l'anàlisi vectorial penal"],
          ["RESULTAT",      "L'agent veu: text DRAG editable | pestanya BD amb fitxes | pestanya Penal amb ranking d'infraccions"],
        ],
        [C.navy, C.steel, C.steel, C.blue, C.blue, C.blue, C.green, C.blue, C.blue, C.steel, C.accent, C.green]
      ),

      new Paragraph({ spacing: { before: 300 }, children: [new TextRun("")] }),

      // --- VARIANT 2 ---
      hd2("Variant B — Flux Ràpid (Mode Parte Diari)"),
      body("Idèntic a la Variant A però Claude genera una entrada de bitàcola breu (60-100 paraules) en lloc d'un informe extensiu. El prompt al redactor_system.txt inclou la instrucció de mode al final."),

      fluxDiagram(
        "flux_b",
        [
          ["AGENT",        "Text col·loquial breu o dictat per veu (Mode Patrulla)"],
          ["BACKEND NODE", "Proxy a Sherlock amb mode: 'parte'"],
          ["SHERLOCK",     "Pipeline complet idèntic (PAS 1→6)"],
          ["CLAUDE",       "Genera entrada breu 60-100 paraules al prompt: MODE: ENTRADA DE BITÀCOLA BREU"],
          ["FRONTEND",     "Text curt per afegir directament a la taula del torn. Pestanya BD i Penal disponibles."],
        ],
        [C.navy, C.steel, C.blue, C.green, C.green]
      ),

      new Paragraph({ spacing: { before: 300 }, children: [new TextRun("")] }),

      // --- VARIANT 3 ---
      hd2("Variant C — Flux Mode Patrulla (Veu)"),
      body("Activat prement el botó 'Mode Treball'. El micròfon utilitza l'API Web SpeechRecognition del navegador en català (ca-ES) amb reconeixement continu mentre es manté premut."),

      fluxDiagram(
        "flux_c",
        [
          ["AGENT",        "Mant\u00e9 premut el bot\u00f3 micr\u00f2fon (mouse/touch)"],
          ["NAVEGADOR",    "SpeechRecognition ca-ES transcriu la veu en temps real → afegeix al textarea"],
          ["AGENT",        "Revisa i corregeix si cal. Prem 'Processar amb IA'"],
          ["PIPELINE",     "Continua idèntic a Variant A o B segons el mode seleccionat"],
        ],
        [C.navy, C.steel, C.blue, C.green]
      ),

      pageBreak(),

      // =====================================================================
      // 3. SISTEMA DE REDACCIÓ DRAG
      // =====================================================================
      hd1("3. Sistema de Redacció Tècnica DRAG"),
      sep(),
      body("La redacció tècnica és la funcionalitat nuclear del sistema. Transforma qualsevol text informal, incorrecte o col·loquial en un informe policial professional en català seguint el sistema DRAG (format estàndard de la Guàrdia Municipal de Catalunya)."),

      hd2("3.1 El Prompt del Redactor"),
      body("El fitxer redactor_system.txt conté les instruccions per a Claude. Ha evolucionat significativament al llarg del projecte. Les regles crítiques actuals són:"),

      simpleTable(
        ["Regla", "Descripció"],
        [
          [{ text: "MANTÉN ELS FETS", bold: true }, "Prohibit inventar matrícules, DNIs, noms o adreces no presents en el text o en un marcador"],
          [{ text: "PROHIBIT TIPIFICAR", bold: true }, "El redactor NO pot escriure 'presumpte delicte de...' ni cap qualificació jurídica. La tipificació la fa el mòdul penal."],
          [{ text: "CATALÀ FORMAL", bold: true }, "Primera persona, cronologia dels fets, llenguatge descriptiu i neutre"],
          [{ text: "RESPECTAR MARCADORS", bold: true }, "Els [[...]] han de copiar-se exactament al text de sortida. El frontend els necessita per les anotacions."],
          [{ text: "MARCADORS EXACTO", bold: true }, "Utilitza les dades del marcador al text: matrícula, marca/model verificats a la BD"],
          [{ text: "MARCADORS PARCIAL", bold: true }, "Indica que la identitat és 'pendent de verificació amb la BD'. Tots els candidats separats per coma."],
          [{ text: "MARCADORS NOU", bold: true }, "Entitats no trobades a la BD: posar en MAJÚSCULES per destacar-les a l'agent."],
        ],
        [2600, 6426]
      ),

      hd2("3.2 Modes de Sortida"),
      simpleTable(
        ["Mode", "Longitud", "Ús típic"],
        [
          [{ text: "Parte Diari", bold: true }, "60-100 paraules", "Anotacions breus del torn: parades, incidències menors, contactes"],
          [{ text: "Informe Tipificat DRAG", bold: true }, "250-400 paraules", "Fets amb entitat jurídica, denúncies, accidents, detencions"],
        ],
        [2500, 2200, 4326]
      ),

      hd2("3.3 Model Claude Seleccionat"),
      body("S'utilitza claude-3-haiku-20240307 per a la redacció DRAG. La decisió és intencional: Haiku és significativament més ràpid i econòmic per a tasques de reformatació de text, on la velocitat de resposta és crítica per a un agent en servei. Sonnet es reserva per a tasques més complexes si cal en el futur."),

      pageBreak(),

      // =====================================================================
      // 4. COMPARACIÓ BD — TOTAL I PARCIAL
      // =====================================================================
      hd1("4. Sistema de Comparació amb la Base de Dades"),
      sep(),
      body("El MatcherService és completament determinista (sense IA). Compara les entitats extretes del text contra hermano_mayor.db i classifica cada coincidència en tres nivells."),

      hd2("4.1 Nivells de Coincidència"),

      simpleTable(
        ["Nivell", "Color Frontend", "Lògica", "Exemple"],
        [
          [{ text: "EXACTO", bold: true, color: C.exacto }, "Blau", "Matrícula idèntica (normalitzada) o DNI exacte a la BD", "9915GBN → registre BD trobat"],
          [{ text: "PARCIAL", bold: true, color: C.parcial }, "Taronja", "Persona: mínim 2 tokens del nom coincideixen a la BD (umbral 70%)", "'Luz Gangas' → candidat 'Luz Estrella Gangas Alvear' (75%)"],
          [{ text: "NOU", bold: true, color: C.nou }, "Verd", "Cap coincidència a la BD — entitat nova no registrada", "Matrícula o persona no registrada"],
          [{ text: "SIN_COINCIDENCIA", bold: true, color: C.gray3 }, "Gris", "Igual que NOU però marcat al marcador per al redactor", "Ubicació no indexada"],
        ],
        [1600, 1400, 3600, 2426]
      ),

      hd2("4.2 Matching de Vehicles"),
      body("El matching de vehicles aplica dos nivells en cascada:"),
      bullet("Cerca exacta: normalitza la matrícula (treu espais i guions, majúscules) i compara contra el camp plate de la taula vehicles."),
      bullet("Cerca parcial: si no hi ha coincidència exacta, cerca matrícules similars amb LIKE sobre els primers 4 caràcters. Retorna els 5 candidats més propers."),

      hd2("4.3 Matching de Persones — TokenMatcher"),
      body("El matching de persones és el component més sofisticat del MatcherService. El sistema utilitza un TokenMatcher basat en tokens per gestionar els casos difícils del nom policial:"),

      simpleTable(
