{"language": "javascript", "code": "const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  HeadingLevel, AlignmentType, BorderStyle, WidthType, ShadingType,
  PageBreak, LevelFormat, UnderlineType
} = require('docx');
const fs = require('fs');

// ============================================================================
// PALETA DE COLORS — Identitat visual Bitàcola
// ============================================================================
const C = {
  navy:     "0D1B2A",
  blue:     "1B263B",
  steel:    "415A77",
  light:    "778DA9",
  accent:   "FB8500",
  green:    "2D6A4F",
  red:      "C1121F",
  white:    "FFFFFF",
  gray1:    "F8F9FA",
  gray2:    "DEE2E6",
  gray3:    "6C757D",
  black:    "000000",
  // Estat
  exacto:   "0066CC",
  parcial:  "E6A817",
  nou:      "198754",
};

// ============================================================================
// HELPERS
// ============================================================================
const border1 = { style: BorderStyle.SINGLE, size: 1, color: C.gray2 };
const borders  = { top: border1, bottom: border1, left: border1, right: border1 };

function hd1(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_1,
    spacing: { before: 400, after: 200 },
    children: [new TextRun({ text, font: "Arial", size: 36, bold: true, color: C.navy })],
  });
}

function hd2(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_2,
    spacing: { before: 320, after: 160 },
    children: [new TextRun({ text, font: "Arial", size: 28, bold: true, color: C.blue })],
  });
}

function hd3(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_3,
    spacing: { before: 200, after: 100 },
    children: [new TextRun({ text, font: "Arial", size: 24, bold: true, color: C.steel })],
  });
}

function body(text, opts = {}) {
  return new Paragraph({
    spacing: { before: 80, after: 80 },
    children: [new TextRun({
      text,
      font: "Arial",
      size: 22,
      color: opts.color || "222222",
      bold: opts.bold || false,
      italics: opts.italic || false,
    })],
  });
}

function bodyRuns(runs) {
  return new Paragraph({
    spacing: { before: 80, after: 80 },
    children: runs.map(r => new TextRun({
      text: r.text,
      font: "Arial",
      size: 22,
      color: r.color || "222222",
      bold: r.bold || false,
      italics: r.italic || false,
    })),
  });
}

function bullet(text, opts = {}) {
  return new Paragraph({
    numbering: { reference: "bullets", level: opts.level || 0 },
    spacing: { before: 60, after: 60 },
    children: [new TextRun({
      text,
      font: "Arial",
      size: 22,
      color: opts.color || "222222",
      bold: opts.bold || false,
    })],
  });
}

function code(text) {
  return new Paragraph({
    spacing: { before: 60, after: 60 },
    indent: { left: 360 },
    children: [new TextRun({
      text,
      font: "Courier New",
      size: 18,
      color: C.navy,
    })],
  });
}

function sep() {
  return new Paragraph({
    spacing: { before: 200, after: 200 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 4, color: C.steel, space: 1 } },
    children: [new TextRun("")],
  });
}

function pageBreak() {
  return new Paragraph({ children: [new PageBreak()] });
}

function badgePar(label, color) {
  return new Paragraph({
    spacing: { before: 60, after: 60 },
    children: [new TextRun({
      text: `  ${label}  `,
      font: "Arial",
      size: 20,
      bold: true,
      color: C.white,
      highlight: undefined,
      shading: { type: ShadingType.CLEAR, fill: color },
    })],
  });
}

// Taula simple
function simpleTable(headers, rows, colWidths) {
  const totalW = colWidths.reduce((a, b) => a + b, 0);
  const headerRow = new TableRow({
    tableHeader: true,
    children: headers.map((h, i) => new TableCell({
      borders,
      width: { size: colWidths[i], type: WidthType.DXA },
      shading: { fill: C.navy, type: ShadingType.CLEAR },
      margins: { top: 80, bottom: 80, left: 120, right: 120 },
      children: [new Paragraph({
        children: [new TextRun({ text: h, font: "Arial", size: 20, bold: true, color: C.white })]
      })],
    })),
  });

  const dataRows = rows.map((row, ri) => new TableRow({
    children: row.map((cell, ci) => new TableCell({
      borders,
      width: { size: colWidths[ci], type: WidthType.DXA },
      shading: { fill: ri % 2 === 0 ? "F8F9FA" : C.white, type: ShadingType.CLEAR },
      margins: { top: 80, bottom: 80, left: 120, right: 120 },
      children: [new Paragraph({
        children: [new TextRun({
          text: cell.text || cell,
          font: "Arial", size: 20,
          bold: cell.bold || false,
          color: cell.color || "333333",
        })]
      })],
    })),
  }));

  return new Table({
    width: { size: totalW, type: WidthType.DXA },
    columnWidths: colWidths,
    rows: [headerRow, ...dataRows],
  });
}

// Caixa destacada
function infoBox(title, lines, fillColor) {
  const cellContent = [
    new Paragraph({
      spacing: { before: 60, after: 80 },
      children: [new TextRun({ text: title, font: "Arial", size: 22, bold: true, color: C.navy })]
    }),
    ...lines.map(l => new Paragraph({
      spacing: { before: 40, after: 40 },
      children: [new TextRun({ text: l, font: "Arial", size: 20, color: "333333" })]
    })),
  ];
  return new Table({
    width: { size: 9026, type: WidthType.DXA },
    columnWidths: [9026],
    rows: [new TableRow({
      children: [new TableCell({
        borders: {
          top:    { style: BorderStyle.SINGLE, size: 4, color: C.accent },
          bottom: { style: BorderStyle.SINGLE, size: 1, color: C.gray2 },
          left:   { style: BorderStyle.SINGLE, size: 12, color: C.accent },
          right:  { style: BorderStyle.SINGLE, size: 1, color: C.gray2 },
        },
        shading: { fill: fillColor || "FFF8F0", type: ShadingType.CLEAR },
        margins: { top: 120, bottom: 120, left: 200, right: 120 },
        children: cellContent,
      })],
    })],
  });
}

// ============================================================================
// DIAGRAMA DE FLUX com a taula ASCII visual
// ============================================================================
function fluxRow(label, desc, color) {
  return new TableRow({
    children: [
      new TableCell({
        borders,
        width: { size: 2200, type: WidthType.DXA },
        shading: { fill: color, type: ShadingType.CLEAR },
        margins: { top: 100, bottom: 100, left: 140, right: 140 },
        children: [new Paragraph({
          alignment: AlignmentType.CENTER,
          children: [new TextRun({ text: label, font: "Arial", size: 20, bold: true, color: C.white })]
        })],
      }),
      new TableCell({
        borders,
        width: { size: 6826, type: WidthType.DXA },
        shading: { fill: "FAFAFA", type: ShadingType.CLEAR },
        margins: { top: 100, bottom: 100, left: 140, right: 140 },
        children: [new Paragraph({
          children: [new TextRun({ text: desc, font: "Arial", size: 20, color: "333333" })]
        })],
      }),
    ],
  });
}

function arrowRow() {
  return new TableRow({
    children: [
      new TableCell({
        borders: { top: border1, bottom: border1, left: { style: BorderStyle.NONE }, right: { style: BorderStyle.NONE } },
        width: { size: 2200, type: WidthType.DXA },
        shading: { fill: C.white, type: ShadingType.CLEAR },
        margins: { top: 20, bottom: 20, left: 140, right: 140 },
        children: [new Paragraph({
          alignment: AlignmentType.CENTER,
          children: [new TextRun({ text: "▼", font: "Arial", size: 24, color: C.steel })]
        })],
      }),
      new TableCell({
        borders: { top: border1, bottom: border1, left: { style: BorderStyle.NONE }, right: { style: BorderStyle.NONE } },
        width: { size: 6826, type: WidthType.DXA },
        shading: { fill: C.white, type: ShadingType.CLEAR },
        margins: { top: 20, bottom: 20, left: 140, right: 140 },
        children: [new Paragraph({ children: [new TextRun("")] })],
      }),
    ],
  });
}

function fluxDiagram(title, steps, colors) {
  const rows = [];
  steps.forEach((s, i) => {
    rows.push(fluxRow(s[0], s[1], colors[i % colors.length]));
    if (i < steps.length - 1) rows.push(arrowRow());
  });
  return new Table({
    width: { size: 9026, type: WidthType.DXA },
    columnWidths: [2200, 6826],
    rows,
  });
}

// ============================================================================
// DOCUMENT
// ============================================================================
const doc = new Document({
