// ========== EDITAR TEXTO TÉCNICO ==========
function editTechnical() {
    const textarea = document.getElementById('textTechnical');
    textarea.readOnly = !textarea.readOnly;

    if (!textarea.readOnly) {
        textarea.focus();
        showStatus('Mode edició activat', 'info');
    }
}

// ========== AÑADIR ENCABEZADO ==========
function addHeader() {
    const textarea = document.getElementById('textTechnical');
    const currentText = textarea.value.trim();

    const now = new Date();
    const fecha = now.toLocaleDateString('ca-ES', {
        year: 'numeric',
        month: '2-digit',
        day: '2-digit'
    });
    const hora = now.toLocaleTimeString('ca-ES', {
        hour: '2-digit',
        minute: '2-digit'
    });

    const header = `DATA: ${fecha}\nHORA: ${hora}\n\n${currentText}`;

    textarea.value = header;
    textarea.readOnly = false;
    textarea.focus();
    showStatus('Capçalera afegida. Pots editar el text ara', 'info');
}

