/**
 * BITÀCOLA - Integración con SHERLOCK API
 * 
 * Este archivo muestra cómo integrar el frontend BITÀCOLA
 * con el backend SHERLOCK para enriquecimiento de informes.
 * 
 * Versión: 1.0.0
 */

// ==================== CONFIGURACIÓN ====================

const SHERLOCK_API_URL = 'http://localhost:8000/api/v1';

// ==================== FUNCIONES DE API ====================

/**
 * Enriquecer informe policial
 * 
 * @param {string} textoVago - Relato informal del agente
 * @param {number} agentId - ID del agente (opcional)
 * @returns {Promise<Object>} Resultado del enriquecimiento
 */
async function enrichReport(textoVago, agentId = null) {
    try {
        const response = await fetch(`${SHERLOCK_API_URL}/enrich`, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify({
                texto_vago: textoVago,
                agent_id: agentId,
                session_id: generateSessionId()
            })
        });

        if (!response.ok) {
            throw new Error(`HTTP error! status: ${response.status}`);
        }

        const data = await response.json();
        return data;
    } catch (error) {
        console.error('Error llamando a SHERLOCK API:', error);
        throw error;
    }
}

/**
 * Verificar estado del servicio
 * 
 * @returns {Promise<Object>} Estado del sistema
 */
async function checkHealth() {
    try {
        const response = await fetch(`${SHERLOCK_API_URL}/health`);
        return await response.json();
    } catch (error) {
        console.error('Error verificando health:', error);
        return { status: 'error', error: error.message };
    }
}

// ==================== UTILIDADES ====================

function generateSessionId() {
    return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
        const r = Math.random() * 16 | 0;
        const v = c === 'x' ? r : (r & 0x3 | 0x8);
        return v.toString(16);
    });
}

/**
 * Renderizar texto enriquecido con colores
 * 
 * @param {string} textoEnriquecido - Texto con marcas @/**
 * @returns {string} HTML con colores aplicados
 */
function renderEnrichedText(textoEnriquecido) {
    let html = textoEnriquecido;

    // Convertir marcas @ a spans azules
    html = html.replace(/@(\w+)/g, '<span class="match-exacto">$1</span>');

    // Convertir marcas ** a spans naranjas
    html = html.replace(/\*\*([^*]+)\*\*/g, '<span class="match-parcial">$1</span>');

    // Preservar saltos de línea
    html = html.replace(/\n/g, '<br>');

    return html;
}

// ==================== INTEGRACIÓN CON BITÀCOLA ====================

/**
 * Función principal de integración
 * Reemplaza o extiende el botón "Generar DRAG" de BITÀCOLA
 */
async function procesarActuacionConSherlock() {
    // 1. Obtener texto del textarea (adaptado a tu HTML)
    const textoVago = document.getElementById('inputText').value;

    if (!textoVago.trim()) {
        alert('Por favor, dicta o escribe una actuación primero');
        return;
    }

    // 2. Mostrar loading
    mostrarLoading(true);

    try {
        // 3. Llamar a SHERLOCK
        const resultado = await enrichReport(textoVago, 1009); // Agent ID desde session/localStorage

        // 4. Mostrar resultados en pestañas
        mostrarResultados(resultado);

    } catch (error) {
        console.error('Error:', error);
        alert('Error procesando informe: ' + error.message);
    } finally {
        mostrarLoading(false);
    }
}

/**
 * Mostrar resultados en pestañas
 */
function mostrarResultados(resultado) {
    // Pestaña "Informe" - Texto enriquecido
    const informeTab = document.getElementById('tab-informe');
    if (informeTab) {
        informeTab.innerHTML = renderEnrichedText(resultado.texto_enriquecido);
    }

    // Pestaña "DB" - Explicación de BD
    const dbTab = document.getElementById('tab-db');
    if (dbTab) {
        dbTab.innerHTML = `<pre>${resultado.explicacion_db}</pre>`;
    }

    // Metadata (opcional)
    console.log('Metadata:', resultado.metadata);

    // Si hay warnings, mostrarlos
    if (resultado.metadata.warnings && resultado.metadata.warnings.length > 0) {
        mostrarWarnings(resultado.metadata.warnings);
    }
}

/**
 * Mostrar warnings al usuario
 */
function mostrarWarnings(warnings) {
    const warningsDiv = document.getElementById('warnings-container');
    if (!warningsDiv) return;

    warningsDiv.innerHTML = warnings.map(w => 
        `<div class="warning">⚠️ ${w}</div>`
    ).join('');
}

/**
 * Loading indicator
 */
function mostrarLoading(show) {
    const spinner = document.getElementById('loading-spinner');
    if (spinner) {
        spinner.style.display = show ? 'block' : 'none';
    }

    const btn = document.getElementById('btn-procesar');
    if (btn) {
        btn.disabled = show;
        btn.textContent = show ? 'Procesando...' : 'Generar Informe';
    }
}

// ==================== CSS NECESARIO ====================

const SHERLOCK_STYLES = `
<style>
    /* Marcas de coincidencia exacta (azul) */
    .match-exacto {
        color: #0066cc;
        font-weight: bold;
        background-color: rgba(0, 102, 204, 0.1);
        padding: 2px 4px;
        border-radius: 3px;
    }

    /* Marcas de coincidencia parcial (naranja) */
    .match-parcial {
        color: #ff8800;
        font-weight: bold;
        background-color: rgba(255, 136, 0, 0.1);
        padding: 2px 4px;
        border-radius: 3px;
    }

    /* Warnings */
    .warning {
        background-color: #fff3cd;
        border: 1px solid #ffc107;
        padding: 10px;
        margin: 5px 0;
        border-radius: 5px;
        color: #856404;
    }

    /* Pestaña DB */
    #tab-db pre {
        background-color: #f5f5f5;
        padding: 15px;
        border-radius: 5px;
        overflow-x: auto;
        font-family: 'Courier New', monospace;
        font-size: 14px;
        line-height: 1.6;
    }

    /* Loading spinner */
    #loading-spinner {
        display: none;
        text-align: center;
        padding: 20px;
