/**
 * BITÀCOLA BACKEND — Pipeline 1
 * ==============================
 *
 * RESPONSABILITAT:
 *   Rebre text informal de l'agent i retornar-lo redactat en format DRAG.
 *   Tot el processament de BD, entitats i anotacions és responsabilitat
 *   de Sherlock (Pipeline 2).
 *
 * FLUX:
 *   Agent (veu/text) → POST /api/translate → Claude redacta DRAG → frontend
 *
 * EL QUE NO FA AQUEST SERVEI:
 *   - Extreure entitats
 *   - Consultar la BD policial
 *   - Calcular similituds
 *   - Generar anotacions
 *   (Tot això és Sherlock /api/v1/analyze)
 */

import express from "express";
import cors    from "cors";
import fetch   from "node-fetch";
import crypto  from "crypto";

const app  = express();
const PORT = process.env.PORT || 10000;
const CLAUDE_API_KEY = process.env.CLAUDE_API_KEY;

if (!CLAUDE_API_KEY) {
  console.error("❌ CLAUDE_API_KEY no configurada");
  process.exit(1);
}

app.use(express.json());
app.use(cors({
  origin: "https://gienini2.github.io",
  methods: ["POST"],
  allowedHeaders: ["Content-Type"],
}));

// ============================================================================
// CONTROL D'ACCÉS BETA
// ============================================================================

const BETA_LIMITS = { parte: 100, informe: 10 };
const userUsage   = {};           // En producció, persistir a Redis/DB

function consumirUso(userId, mode) {
  if (!userUsage[userId]) userUsage[userId] = { parte: 0, informe: 0 };
  const mode_key = mode === "informe" ? "informe" : "parte";
  if (userUsage[userId][mode_key] >= BETA_LIMITS[mode_key]) return false;
  userUsage[userId][mode_key]++;
  return true;
}

app.post("/api/check-beta", (req, res) => {
  const { user_id } = req.body;
  // Per ara qualsevol user_id vàlid té accés (ampliar amb whitelist si cal)
  res.json({ has_access: !!user_id });
});

// ============================================================================
// PROMPTS DE REDACCIÓ DRAG
// ============================================================================

const PROMPT_PARTE = `
Ets un redactor d'actuacions policials operatives per a la Guàrdia Municipal de Catalunya.

TASCA:
Transforma el text col·loquial en una ENTRADA DE BITÀCOLA professional.

CRITERIS:
- Llenguatge formal i impersonal
- 4-6 línies (60-100 paraules)
- Comença amb: "A les [HORA] hores,"
- NO inventis dades
- NO infereixis professions ni context no explícit
- No afegeixis conclusions ni valoracions
- Utilitza "acta de denúncia" per fets administratius
- Reserva "diligències" exclusivament per fets penals

RESPON NOMÉS AMB EL TEXT FINAL.
`.trim();

const PROMPT_INFORME = `
Ets un redactor d'informes policials per a la Guàrdia Municipal de Catalunya.

TASCA:
Redacta un INFORME POLICIAL EXTENSIU en català.

CRITERIS:
- Llenguatge formal, tècnic i jurídic
- 250-400 paraules
- Estructura: FETS / ACTUACIÓ POLICIAL / VALORACIÓ ORIENTATIVA / RESULTAT
- No inventis dades
- No citis articles concrets
- "Diligències" només per delictes
- "Acta de denúncia" per àmbit administratiu

INICI:
Si detectes patrulla/agents/vehicle → formula completa.
Si no → "A les [HORA] hores,"

RESPON NOMÉS AMB L'INFORME.
`.trim();

// ============================================================================
// ENDPOINT: REDACCIÓ DRAG
// ============================================================================

/**
 * POST /api/translate
 *
 * Body:  { text, mode, user_id }
 *   text:    text informal de l'agent
 *   mode:    "parte" | "informe"
 *   user_id: identificador de sessió
 *
 * Response: { translation: string }
 *   translation: text redactat en format DRAG
 *
 * NOTA: El frontend rep aquest text i ELL decideix si crida Sherlock.
 * Aquest backend NO crida Sherlock.
 */
app.post("/api/translate", async (req, res) => {
  const { text, mode = "parte", user_id } = req.body;

  if (!text || typeof text !== "string" || !text.trim()) {
    return res.status(400).json({ error: "Text invàlid o buit" });
  }
  if (!user_id) {
    return res.status(401).json({ error: "Usuari no autoritzat" });
  }
  if (!consumirUso(user_id, mode)) {
    return res.status(403).json({ error: "Límit d'ús beta assolit per aquest mode" });
  }

  const prompt = mode === "informe" ? PROMPT_INFORME : PROMPT_PARTE;

  try {
    const response = await fetch("https://api.anthropic.com/v1/messages", {
      method: "POST",
      headers: {
        "Content-Type":      "application/json",
        "x-api-key":         CLAUDE_API_KEY,
        "anthropic-version": "2023-06-01",
      },
      body: JSON.stringify({
        model:      "claude-sonnet-4-20250514",
        max_tokens: 900,
        messages: [{
          role:    "user",
          content: `${prompt}\n\nTEXT DE L'AGENT:\n${text.trim()}`,
        }],
      }),
    });

    if (!response.ok) {
      const err = await response.text();
      console.error("❌ Claude API error:", err);
      return res.status(500).json({ error: "Error en Claude API" });
    }

    const data   = await response.json();
    const output = data.content?.[0]?.text ?? "";

    console.log(`✅ Traducció completada [mode=${mode}, user=${user_id}]`);
    res.json({ translation: output });

  } catch (err) {
    console.error("🔥 Error general:", err);
    res.status(500).json({ error: "Error intern del servidor" });
  }
});

// ============================================================================
// ENDPOINT: LOG D'ÚS (telemetria)
// ============================================================================

app.post("/api/log", (req, res) => {
  const { user_id, mode, action, ts } = req.body;
  console.log(`[LOG] user=${user_id} mode=${mode} action=${action} ts=${ts}`);
  res.json({ ok: true });
});

// ============================================================================
// ARRANC
// ============================================================================

app.listen(PORT, () => {
  console.log(`🚀 Bitàcola Backend actiu al port ${PORT}`);
  console.log(`   Pipeline 1: redacció DRAG`);
  console.log(`   Pipeline 2 (entitats): Sherlock independent`);
});

