        /* Anotacions */
        .entity-exact {
            background: #cce5ff;
            border-bottom: 2px solid #0066cc;
            padding: 1px 3px;
            border-radius: 2px;
            cursor: pointer;
        }

        .entity-partial {
            background: #fff3cd;
            border-bottom: 2px solid #e6a817;
            padding: 1px 3px;
            border-radius: 2px;
            cursor: pointer;
        }

        /* Panel penal */
        #panelPenal, #panelDB {
            padding: 10px;
            min-height: 100px;
        }

        @media (max-width: 600px) {
            body { padding: 10px; }
            .container { padding: 20px; border-radius: 12px; }
            .mic-btn { height: 110px; font-size: 18px; }
            table { font-size: 13px; }
            th, td { padding: 12px 8px; }
            .btn { padding: 14px; font-size: 14px; }
        }

        @media (min-width: 1024px) {
            .container { max-width: 1100px; padding: 45px; }
            th, td { padding: 18px 16px; }
        }
    </style>
</head>
<body>
