        }

        .tab-btn {
            padding: 10px 20px;
            border: none;
            border-radius: 8px 8px 0 0;
            background: #e9ecef;
            color: #6c757d;
            font-size: 13px;
            font-weight: 700;
            cursor: pointer;
            text-transform: uppercase;
            letter-spacing: 0.5px;
            transition: all 0.2s;
            border-bottom: 2px solid transparent;
            margin-bottom: -2px;
        }

        .tab-btn.active {
            background: white;
            color: #1b263b;
            border-color: #dee2e6;
            border-bottom-color: white;
        }

        .tab-btn:hover:not(.active) { background: #dee2e6; }

        .tab-panel { display: none; }
        .tab-panel.active { display: block; }

        /* ===== BOTONS ===== */
        .btn-row {
            display: flex;
            gap: 10px;
            margin-bottom: 20px;
            align-items: center;
        }

        .mode-toggle-btn {
            padding: 10px 16px;
            border: 2px solid #6c757d;
            border-radius: 8px;
            background: #6c757d;
            color: white;
            font-size: 12px;
            font-weight: 700;
            cursor: pointer;
            transition: all 0.3s;
            text-transform: uppercase;
            letter-spacing: 0.5px;
            white-space: nowrap;
        }

        .mode-toggle-btn.active { background: #2d6a4f; border-color: #2d6a4f; }

        .mic-btn {
            width: 100%;
            height: 90px;
            background: linear-gradient(135deg, #c1121f 0%, #9d0208 100%);
            border: none;
            border-radius: 12px;
            color: white;
            font-size: 15px;
            font-weight: 700;
            cursor: pointer;
            margin-bottom: 20px;
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 12px;
            box-shadow: 0 8px 20px rgba(193,18,31,0.4);
            transition: all 0.3s ease;
            text-transform: uppercase;
            letter-spacing: 1px;
        }

        .mic-btn.recording {
            background: linear-gradient(135deg, #dc2f02 0%, #d00000 100%);
            animation: pulse 1.5s infinite;
        }

        .mic-icon { width: 24px; height: 24px; fill: white; }

        @keyframes pulse { 0%,100%{opacity:1} 50%{opacity:0.8} }

        .input-group { margin-bottom: 18px; }

        .input-group label {
            display: block;
            font-size: 13px;
            font-weight: 700;
            color: #415a77;
            margin-bottom: 10px;
            text-transform: uppercase;
            letter-spacing: 0.5px;
        }

        textarea, select {
            width: 100%;
            padding: 16px;
            border: 2px solid #dee2e6;
            border-radius: 10px;
            font-size: 15px;
            font-family: inherit;
            resize: vertical;
            transition: all 0.3s;
        }

        textarea:focus, select:focus {
            outline: none;
            border-color: #415a77;
            box-shadow: 0 0 0 3px rgba(65,90,119,0.1);
        }

        select { resize: none; cursor: pointer; background: white; }

        .textarea-original  { min-height: 90px; }
        .textarea-technical {
            min-height: 160px;
            background: #f8f9fa;
            border-color: #198754;
            font-family: 'Courier New', monospace;
        }

        .btn-group {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 12px;
            margin-bottom: 20px;
