# annotator/text_marker.py

def mark_text(text: str, resolutions: list) -> str:
    for r in resolutions:
        if r["match"] == "exact":
            text = text.replace(r["entity"], f"@{r['entity']}")
        elif r["match"] == "partial":
            text = text.replace(r["entity"], f"**{r['entity']}**")
    return text

# resolver/similarity.py

def plate_similarity(a: str, b: str) -> float:
    matches = sum(1 for x, y in zip(a, b) if x == y)
    return matches / max(len(a), len(b))

# resolver/resolver.py

from resolver.similarity import plate_similarity

def resolve_vehicle(plate: str, db) -> dict:
    exact = db.get_vehicle_exact(plate)
    if exact:
        return {
            "entity": plate,
            "type": "vehicle",
            "match": "exact",
            "facts": {
                "marca": exact["marca"],
                "modelo": exact["modelo"],
                "titular": exact["titular"],
                "apariciones": db.get_vehicle_history_count(plate)
            }
        }

    similars = db.get_vehicle_similar(plate)
    for v in similars:
        if plate_similarity(plate, v["matricula"]) >= 0.7:
            return {
                "entity": plate,
                "type": "vehicle",
                "match": "partial",
                "facts": {
                    "similar_plate": v["matricula"]
                }
            }

    return {
        "entity": plate,
        "type": "vehicle",
        "match": "none",
        "facts": {}
    }

# annotator/db_explainer.py

def explain(resolutions: list) -> list[str]:
    explanations = []

    for r in resolutions:
        if r["match"] == "exact":
            f = r["facts"]
            explanations.append(
                f"La matrícula {r['entity']} consta a la base de dades "
                f"({f['marca']} {f['modelo']}), titular {f['titular']}. "
                f"Apareix en {f['apariciones']} actuacions prèvies."
            )
        elif r["match"] == "partial":
            explanations.append(
                f"La matrícula {r['entity']} presenta coincidència parcial "
                f"amb {r['facts']['similar_plate']}."
            )

    return explanations

# resolver/db_adapter.py

import sqlite3
from typing import Optional, List

class HermanoMayorDB:
    def __init__(self, path: str):
        self.conn = sqlite3.connect(path)
        self.conn.row_factory = sqlite3.Row

    def get_vehicle_exact(self, plate: str) -> Optional[dict]:
        cur = self.conn.execute(
            "SELECT * FROM vehicles WHERE matricula = ?", (plate,)
        )
        row = cur.fetchone()
        return dict(row) if row else None

    def get_vehicle_similar(self, plate: str) -> List[dict]:
        cur = self.conn.execute(
            "SELECT * FROM vehicles WHERE matricula LIKE ?", (f"%{plate[:4]}%",)
        )
        return [dict(r) for r in cur.fetchall()]

    def get_vehicle_history_count(self, plate: str) -> int:
        cur = self.conn.execute(
            "SELECT COUNT(*) as c FROM historial WHERE matricula = ?", (plate,)
        )
        return cur.fetchone()["c"]

