// ========== BUSCAR Y REEMPLAZAR EN index_dev.html ==========

// 1. BORRAR TODA la función translateText() vieja (líneas ~800-900)
//    Desde "async function translateText() {" hasta el "}" que cierra esa función

// 2. MANTENER SOLO la función translateText() nueva (líneas ~1100-1250)
//    Esta es la que tiene:
//    - fetch a /api/v1/enrich
//    - pintarTextoAnotado()
//    - renderizarPanelDB()

// ========== VERSIÓN CORRECTA (COPIAR COMPLETO) ==========

async function translateText() {
    const mode = document.getElementById("modeSelect").value;
    const originalText = document.getElementById("textOriginal").value.trim();

    if (!originalText) {
        showStatus("Escriu o dicta alguna cosa primer", "error");
        return;
    }

    document.getElementById('loader').classList.add('show');
    document.getElementById('translateBtn').disabled = true;
    showStatus('Processant amb Claude...', 'info');

    try {
        // PASO 1: Redactar con bitacola-backend
        const response = await fetch(
            "https://bitacola-backend.onrender.com/api/translate",
            {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({
                    text: originalText,
                    mode: mode,
                    user_id: localStorage.getItem("user_id")
                })
            }
        );
        logUsage("translate");

        const data = await response.json();

        if (!response.ok) {
            showStatus(`Error: ${data.error}`, "error");
            return;
        }

        const now = new Date();
        const hora = now.toLocaleTimeString("ca-ES", {
            hour: "2-digit",
            minute: "2-digit"
        });

        const textoDRAG = data.translation.replace(/\[HORA\]/g, hora);

        // Mostrar texto en textarea normal
        document.getElementById("textTechnical").value = textoDRAG;
        document.getElementById("textTechnical").style.display = "block";

        // PASO 2: Analizar con Sherlock (extracción + matching + anotación)
        showStatus('Analitzant amb Sherlock...', 'info');

        const sherlockResponse = await fetch(
            "https://sherlock-backend-flwb.onrender.com/api/v1/enrich",
            {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({
                    texto_vago: textoDRAG
                })
            }
        );

        const sherlockData = await sherlockResponse.json();

        if (!sherlockResponse.ok) {
            console.error("Error Sherlock:", sherlockData);
            // Fallback: mostrar mensaje genérico en panel DB
            const panel = document.getElementById("panelDB");
            panel.innerHTML = "<p style='color:#666;'>⚠️ Error consultant base de dades.</p>";
        } else {
            // PASO 3: Generar explicaciones DB
            showStatus('Consultant base de dades...', 'info');

            const explicacionesResponse = await fetch(
                "https://sherlock-backend-flwb.onrender.com/api/v1/explain",
                {
                    method: "POST",
                    headers: { "Content-Type": "application/json" },
                    body: JSON.stringify({
                        matches: sherlockData.matches
                    })
                }
            );

            const explicacionesData = await explicacionesResponse.json();

            // Renderizar panel DB
            renderizarPanelDB(explicacionesData.explicaciones);
        }

        // Mostrar secciones
        document.getElementById("technicalGroup").style.display = "block";
        document.getElementById("addBtnGroup").style.display = "grid";
        document.getElementById("finalBtnGroup").style.display = "grid";

        showStatus("Anàlisi completada", "success");

    } catch (e) {
        console.error(e);
        showStatus("Error en l'anàlisi: " + e.message, "error");
    } finally {
        document.getElementById('loader').classList.remove('show');
        document.getElementById('translateBtn').disabled = false;
    }
}

