    </style>
</head>
<body>
    <div class="container">
        <div class="header-container">
            <div class="header-content">
                <h1>Bitàcola de Servei</h1>
                <p class="subtitle">Registre Policial d'Actuacions</p>
            </div>
        </div>

        <button class="mic-btn" id="micBtn" style="display: none;">
            <svg class="mic-icon" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg">
                <path d="M12 14c1.66 0 3-1.34 3-3V5c0-1.66-1.34-3-3-3S9 3.34 9 5v6c0 1.66 1.34 3 3 3z"/>
                <path d="M17 11c0 2.76-2.24 5-5 5s-5-2.24-5-5H5c0 3.53 2.61 6.43 6 6.92V21h2v-3.08c3.39-.49 6-3.39 6-6.92h-2z"/>
            </svg>
            <span id="micText">Mantenir premut per dictar</span>
        </button>

        <div id="status" class="status"></div>
        <div id="loader" class="loader"></div>

        <div class="input-group">
            <label>Tipus de sortida</label>
            <select id="modeSelect">
                <option value="parte">Parte Diari</option>
                <option value="informe">Informe Tipificat DRAG</option>
            </select>
        </div>

        <div style="display:flex; border-bottom:1px solid #ccc; margin-top:20px;">
          <button id="tabRedactor" class="tabActive">REDACTOR</button>
          <button id="tabDB">DB</button>
        </div>

        <div id="panelRedactor">
            <div class="input-group">
                <label>Text original (dictat o escrit)</label>
                <textarea id="textOriginal" class="textarea-original" placeholder="Escriu aquí o utilitza el botó de veu..."></textarea>
            </div>
        </div>

        <div id="panelDB" style="display:none; padding:10px; background:#f8f8f8; min-height:100px;">
          <p style='color:#999; font-style:italic;'>Processa un text primer per veure coincidències amb la base de dades.</p>
        </div>

        <div class="btn-row">
            <button class="mode-toggle-btn" id="modeToggleBtn" onclick="toggleWorkMode()">
                MODE TREBALL
            </button>
            <button class="btn btn-translate" id="translateBtn" onclick="translateText()">
                ⚡ PROCESSAR AMB IA
            </button>
            <button class="btn btn-clear" onclick="clearAll()">
                ✕ ESBORRAR
            </button>
        </div>

        <div class="input-group" id="technicalGroup" style="display: none;">
            <label>Text tècnic generat</label>
            <textarea id="textTechnical" class="textarea-technical" readonly></textarea>
        </div>

        <div class="btn-group" id="addBtnGroup" style="display: none;">
            <button class="btn btn-clear" onclick="addHeader()">
                ▤ CAPÇALERA
            </button>
            <button class="btn btn-clear" onclick="editTechnical()">
                ✎ EDITAR
            </button>
        </div>

        <div class="btn-group" id="finalBtnGroup" style="display: none;">
            <button class="btn btn-add" onclick="addRecord()">
                + AFEGIR A BITÀCOLA
            </button>
            <button class="btn btn-clear" onclick="clearAll()">
                ✕ ESBORRAR
            </button>
        </div>

        <h2 style="margin: 30px 0 15px 0; color: #1b263b; font-size: 18px; font-weight: 700; text-transform: uppercase; letter-spacing: 1px; border-bottom: 2px solid #dee2e6; padding-bottom: 10px;">Registres del Torn</h2>

        <table>
            <thead>
                <tr>
                    <th style="width: 12%;">Hora</th>
                    <th style="width: 80%;">Descripció</th>
                    <th style="width: 8%; text-align: center;">✕</th>
                </tr>
            </thead>
            <tbody id="tableBody">
                <tr>
                    <td colspan="3" class="empty">Cap registre encara. Dicta o escriu la teva primera actuació.</td>
                </tr>
            </tbody>
        </table>

        <div class="toggle-container" style="background: #fff3cd; border-color: #ffc107;">
            <input type="checkbox" id="showTimeInExport">
            <label for="showTimeInExport">Mostrar hores en exportar</label>
        </div>

        <button class="btn btn-copy" onclick="exportTXT()">
            ▣ COPIAR BITÀCOLA COMPLETA
        </button>

        <button class="btn btn-delete-all" onclick="deleteAll()">
            ⊗ ESBORRAR TOT EL TORN
        </button>
    </div>

    <script>
        let db;
        let records = [];
        let recognition = null;
        let isRecording = false;

        // ========== INDEXEDDB ==========
        function initDB() {
            const request = indexedDB.open('BitacolaDB', 1);

            request.onerror = () => {
                console.error('❌ Error obrint IndexedDB');
            };

            request.onsuccess = (event) => {
                db = event.target.result;
                console.log('✅ IndexedDB oberta');
                loadFromDB();
            };

            request.onupgradeneeded = (event) => {
                db = event.target.result;
                if (!db.objectStoreNames.contains('records')) {
                    db.createObjectStore('records', { keyPath: 'id' });
                    console.log('📦 ObjectStore "records" creat');
                }
            };
        }

        // ========== TABS ==========
        const tabRedactor = document.getElementById("tabRedactor");
        const tabDB = document.getElementById("tabDB");
        const panelRedactor = document.getElementById("panelRedactor");
        const panelDB = document.getElementById("panelDB");

        tabRedactor.onclick = () => {
          panelRedactor.style.display = "block";
          panelDB.style.display = "none";
          tabRedactor.classList.add("tabActive");
          tabDB.classList.remove("tabActive");
        };

        tabDB.onclick = () => {
          panelRedactor.style.display = "none";
          panelDB.style.display = "block";
          tabDB.classList.add("tabActive");
          tabRedactor.classList.remove("tabActive");
        };

        function saveToDB(record, callback) {
            if (!db) {
                callback(false);
                return;
            }
            const transaction = db.transaction(['records'], 'readwrite');
            const store = transaction.objectStore('records');
            const request = store.add(record);

            request.onsuccess = () => callback(true);
            request.onerror = () => callback(false);
        }

        function loadFromDB() {
            if (!db) return;

            const transaction = db.transaction(['records'], 'readonly');
            const store = transaction.objectStore('records');
            const request = store.getAll();

            request.onsuccess = (event) => {
                records = event.target.result || [];
                records.sort((a, b) => b.id - a.id);
                renderTable();
                console.log(`📚 ${records.length} registres carregats`);
            };
        }

        function deleteFromDB(id, callback) {
            if (!db) {
                callback(false);
                return;
            }
            const transaction = db.transaction(['records'], 'readwrite');
            const store = transaction.objectStore('records');
            const request = store.delete(id);

            request.onsuccess = () => callback(true);
            request.onerror = () => callback(false);
        }

        function clearDB(callback) {
            if (!db) {
                callback(false);
                return;
            }
            const transaction = db.transaction(['records'], 'readwrite');
            const store = transaction.objectStore('records');
            const request = store.clear();

            request.onsuccess = () => callback(true);
            request.onerror = () => callback(false);
        }

        // ========== MODO PATRULLA ==========
        let isPatrolMode = false;

        function toggleWorkMode() {
            isPatrolMode = !isPatrolMode;
            const micBtn = document.getElementById('micBtn');
            const toggleBtn = document.getElementById('modeToggleBtn');

            if (isPatrolMode) {
                micBtn.style.display = 'flex';
                toggleBtn.classList.add('active');
                initSpeechRecognition();
                localStorage.setItem('agent_mode', 'patrol');
                showStatus('Mode Patrulla activat', 'success');
            } else {
                micBtn.style.display = 'none';
                toggleBtn.classList.remove('active');
                if (recognition) {
                    recognition.stop();
                    recognition = null;
                }
                localStorage.setItem('agent_mode', 'office');
                showStatus('Mode Oficina activat', 'info');
            }
        }

        // ========== RECONOCIMIENTO DE VOZ ==========
        function initSpeechRecognition() {
            if (!('webkitSpeechRecognition' in window) && !('SpeechRecognition' in window)) {
                showStatus('El teu navegador no suporta reconeixement de veu', 'error');
                return;
            }

            const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
            recognition = new SpeechRecognition();
            recognition.lang = 'ca-ES';
            recognition.continuous = true;
            recognition.interimResults = false;

            recognition.onresult = (event) => {
                let transcript = '';
                for (let i = event.resultIndex; i < event.results.length; i++) {
                    transcript += event.results[i][0].transcript + ' ';
                }

                const currentText = document.getElementById('textOriginal').value;
                document.getElementById('textOriginal').value = currentText + transcript;
            };

            recognition.onerror = (event) => {
                console.error('Error reconeixement:', event.error);
                if (event.error !== 'no-speech') {
                    showStatus('Error de reconeixement: ' + event.error, 'error');
                }
            };

            recognition.onend = () => {
                if (isRecording) {
                    recognition.start();
                }
            };
        }

        document.getElementById('micBtn').addEventListener('mousedown', startRecording);
        document.getElementById('micBtn').addEventListener('mouseup', stopRecording);
        document.getElementById('micBtn').addEventListener('touchstart', (e) => {
            e.preventDefault();
            startRecording();
        });
        document.getElementById('micBtn').addEventListener('touchend', (e) => {
            e.preventDefault();
            stopRecording();
        });

        function startRecording() {
            if (!recognition) return;

            isRecording = true;
            recognition.start();
            document.getElementById('micBtn').classList.add('recording');
            document.getElementById('micText').textContent = '● GRAVANT...';
            logUsage("voice_start");
        }

        function stopRecording() {
            if (!recognition) return;

            isRecording = false;
            recognition.stop();
            document.getElementById('micBtn').classList.remove('recording');
            document.getElementById('micText').textContent = 'Mantenir premut per dictar';
            logUsage("voice_stop");
        }

        async function checkBetaAccess() {
          let userId = localStorage.getItem("user_id");
          if (!userId) {
            userId = "user_" + Math.random().toString(36).substr(2, 9);
            localStorage.setItem("user_id", userId);
          }

          try {
            const response = await fetch(
              "https://bitacola-backend.onrender.com/api/check-beta",
              {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({ user_id: userId })
              }
            );

            const data = await response.json();

            if (!data.has_access) {
              document.body.innerHTML = `
                <div style="
                  display: flex;
                  flex-direction: column;
                  align-items: center;
                  justify-content: center;
                  min-height: 100vh;
                  background: linear-gradient(135deg, #1e3c72 0%, #2a5298 100%);
                  color: white;
                  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
                  padding: 20px;
                  text-align: center;
                ">
                  <div style="
                    background: white;
                    color: #2a5298;
                    padding: 40px;
                    border-radius: 20px;
                    max-width: 500px;
                    box-shadow: 0 20px 60px rgba(0,0,0,0.3);
                  ">
                    <h1 style="font-size: 48px; margin-bottom: 20px;">⊘</h1>
                    <h2 style="margin-bottom: 15px;">Accés Restringit</h2>
                    <p style="color: #666; line-height: 1.6; margin-bottom: 25px;">
                      Aquesta aplicació està en fase beta privada.<br>
                      El teu ID (<code style="background: #f0f7ff; padding: 2px 8px; border-radius: 4px;">${userId}</code>) no té accés autoritzat.
                    </p>
                    <p style="color: #999; font-size: 14px;">
                      Si creus que hauries de tenir accés, contacta amb l'administrador.
                    </p>
                  </div>
                </div>
              `;
              return;
            }

          } catch (error) {
            console.error("Error verificant accés:", error);
          }
        }

        // ========== RENDERIZAR PANEL DB ==========
        function renderizarPanelDB(explicaciones) {
            const panel = document.getElementById("panelDB");
            panel.innerHTML = "";

            if (!explicaciones || explicaciones.length === 0) {
                panel.innerHTML = "<p style='color:#666;'>✔ No consten coincidències a la base de dades.</p>";
                return;
            }

            explicaciones.forEach(exp => {
                const card = document.createElement("div");
                card.style.cssText = `
                    background: white;
                    border: 2px solid #dee2e6;
                    border-radius: 10px;
                    padding: 20px;
                    margin-bottom: 15px;
                `;

                const riesgoColor = {
                    'ALTO': '#dc3545',
                    'MEDIO': '#ffc107',
                    'BAJO': '#198754'
                }[exp.indicadores.riesgo] || '#6c757d';

                let html = `
                    <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:15px;">
