                        </div>
                        <div style="
                            background: ${riesgoColor};
                            color: white;
                            padding: 8px 16px;
                            border-radius: 6px;
                            font-weight: 700;
                            font-size: 12px;
                        ">
                            ${exp.indicadores.riesgo}
                        </div>
                    </div>
                `;

                html += `<div style="background:#f8f9fa; padding:12px; border-radius:6px; margin-bottom:15px;">`;
                html += `<h4 style="margin:0 0 10px 0; font-size:14px; color:#415a77;">Dades Actuals</h4>`;

                for (const [key, value] of Object.entries(exp.datos_actuales)) {
                    if (value) {
                        html += `<div style="margin:4px 0;"><strong>${key}:</strong> ${value}</div>`;
                    }
                }
                html += `</div>`;

                if (exp.historial && exp.historial.length > 0) {
                    html += `<h4 style="margin:0 0 10px 0; font-size:14px; color:#415a77;">Historial (${exp.historial.length} actuacions)</h4>`;
                    html += `<div style="max-height:200px; overflow-y:auto;">`;

                    exp.historial.forEach((registro, i) => {
                        const fecha = new Date(registro.fecha).toLocaleDateString('ca-ES');

                        html += `
                            <div style="
                                padding:10px;
                                border-left:3px solid #415a77;
                                margin-left:10px;
                                margin-bottom:10px;
                                background:#f8f9fa;
                            ">
                                <div style="font-weight:700; color:#1b263b;">${fecha}</div>
                                <div style="font-size:13px; color:#495057;">${registro.actuacion}</div>
                                <div style="font-size:12px; color:#6c757d;">${registro.ubicacion || ''}</div>
                            </div>
                        `;
                    });

                    html += `</div>`;
                }

                html += `<div style="margin-top:15px; padding-top:15px; border-top:1px solid #dee2e6;">`;
                html += `<small style="color:#6c757d;">`;
