                html += `</div>`;

                card.innerHTML = html;
                panel.appendChild(card);
            });
        }

        // ========== TRADUCCIÓN IA (FUNCIÓN ÚNICA Y CORRECTA) ==========
        async function translateText() {
            const mode = document.getElementById("modeSelect").value;
            const originalText = document.getElementById("textOriginal").value.trim();

            if (!originalText) {
                showStatus("Escriu o dicta alguna cosa primer", "error");
                return;
            }

            document.getElementById('loader').classList.add('show');
            document.getElementById('translateBtn').disabled = true;
            showStatus('Processant amb Claude...', 'info');

            try {
                // PASO 1: Redactar con bitacola-backend
                const response = await fetch(
                    "https://bitacola-backend.onrender.com/api/translate",
                    {
                        method: "POST",
                        headers: { "Content-Type": "application/json" },
                        body: JSON.stringify({
                            text: originalText,
                            mode: mode,
                            user_id: localStorage.getItem("user_id")
                        })
                    }
                );
                logUsage("translate");

                const data = await response.json();

                if (!response.ok) {
                    showStatus(`Error: ${data.error}`, "error");
                    return;
                }

                const now = new Date();
                const hora = now.toLocaleTimeString("ca-ES", {
                    hour: "2-digit",
                    minute: "2-digit"
                });

                const textoDRAG = data.translation.replace(/\[HORA\]/g, hora);

                // Mostrar texto en textarea
                document.getElementById("textTechnical").value = textoDRAG;
                document.getElementById("textTechnical").style.display = "block";

                // PASO 2: Analizar con Sherlock
                showStatus('Analitzant amb Sherlock...', 'info');
                console.log("🔍 Llamando a /api/v1/enrich...");

                const sherlockResponse = await fetch(
                    "https://sherlock-backend-flwb.onrender.com/api/v1/enrich",
                    {
                        method: "POST",
                        headers: { "Content-Type": "application/json" },
                        body: JSON.stringify({
                            texto_vago: textoDRAG
                        })
                    }
                );

                const sherlockData = await sherlockResponse.json();
                console.log("📦 Sherlock data:", sherlockData);

                if (!sherlockResponse.ok) {
                    console.error("❌ Error Sherlock:", sherlockData);
                    const panel = document.getElementById("panelDB");
                    panel.innerHTML = "<p style='color:#dc3545;'>⚠️ Error consultant base de dades.</p>";
                } else {
                    // PASO 3: Generar explicaciones DB
                    showStatus('Consultant base de dades...', 'info');
                    console.log("🔍 Llamando a /api/v1/explain...");

                    const explicacionesResponse = await fetch(
                        "https://sherlock-backend-flwb.onrender.com/api/v1/explain",
                        {
                            method: "POST",
                            headers: { "Content-Type": "application/json" },
                            body: JSON.stringify({
                                matches: sherlockData.matches
                            })
                        }
                    );

                    const explicacionesData = await explicacionesResponse.json();
                    console.log("📊 Explicaciones:", explicacionesData);

                    // Renderizar panel DB
                    renderizarPanelDB(explicacionesData.explicaciones);

                    // CAMBIAR AUTOMÁTICAMENTE A TAB DB
                    tabDB.click();
                }

                // Mostrar secciones
                document.getElementById("technicalGroup").style.display = "block";
                document.getElementById("addBtnGroup").style.display = "grid";
                document.getElementById("finalBtnGroup").style.display = "grid";

                showStatus("Anàlisi completada", "success");

            } catch (e) {
                console.error("💥 Error:", e);
                showStatus("Error en l'anàlisi: " + e.message, "error");
            } finally {
                document.getElementById('loader').classList.remove('show');
                document.getElementById('translateBtn').disabled = false;
            }
        }

        // ========== EDITAR TEXTO TÉCNICO ==========
        function editTechnical() {
            const textarea = document.getElementById('textTechnical');
            textarea.readOnly = !textarea.readOnly;

            if (!textarea.readOnly) {
                textarea.focus();
                showStatus('Mode edició activat', 'info');
            }
        }

        // ========== AÑADIR ENCABEZADO ==========
        function addHeader() {
            const textarea = document.getElementById('textTechnical');
            const currentText = textarea.value.trim();

            const now = new Date();
            const fecha = now.toLocaleDateString('ca-ES', {
                year: 'numeric',
                month: '2-digit',
                day: '2-digit'
            });
            const hora = now.toLocaleTimeString('ca-ES', {
                hour: '2-digit',
                minute: '2-digit'
            });

            const header = `DATA: ${fecha}\nHORA: ${hora}\n\n${currentText}`;

            textarea.value = header;
            textarea.readOnly = false;
            textarea.focus();
            showStatus('Capçalera afegida. Pots editar el text ara', 'info');
        }

        // ========== AÑADIR A BITÁCOLA ==========
        function addRecord() {
            const technicalText = document.getElementById('textTechnical').value.trim();
            const mode = document.getElementById('modeSelect').value;

            if (!technicalText) {
                showStatus('No hi ha text tècnic per afegir', 'error');
                return;
            }

            const now = new Date();
            const time = now.toLocaleTimeString('ca-ES', {
                hour: '2-digit',
                minute: '2-digit'
            });

            const newRecord = {
                id: Date.now(),
                time: time,
                description: technicalText,
                mode: mode
            };

            saveToDB(newRecord, (success) => {
                if (success) {
                    records.unshift(newRecord);
                    renderTable();
                    clearAll();
                    showStatus('Registre afegit a la bitàcola', 'success');
                } else {
                    showStatus('Error guardant registre', 'error');
                }
            });
        }

        // ========== BORRAR REGISTRO ==========
        function deleteRecord(id) {
            if (!confirm('Eliminar aquest registre?')) return;

            deleteFromDB(id, (success) => {
                if (success) {
                    records = records.filter(r => r.id !== id);
                    renderTable();
                    showStatus('Registre eliminat', 'info');
                } else {
                    showStatus('Error eliminant registre', 'error');
                }
            });
        }

        // ========== BORRAR TODO ==========
        function deleteAll() {
            if (records.length === 0) {
                showStatus('No hi ha registres per esborrar', 'error');
                return;
            }

            if (!confirm('⚠️ Segur que vols esborrar TOTS els registres del torn?')) return;

            clearDB((success) => {
                if (success) {
                    records = [];
                    renderTable();
                    showStatus('Tots els registres esborrats', 'info');
                } else {
                    showStatus('Error esborrant registres', 'error');
                }
            });
        }

        // ========== RENDERIZAR TABLA ==========
        function renderTable() {
            const tbody = document.getElementById('tableBody');

            if (records.length === 0) {
                tbody.innerHTML = '<tr><td colspan="3" class="empty">Cap registre encara. Dicta o escriu la teva primera actuació.</td></tr>';
                return;
            }

            let html = '';
            records.forEach(record => {
                const modeIcon = record.mode === 'informe' ? '■' : '▪';
                html += `
                    <tr>
                        <td><strong>${record.time}</strong></td>
                        <td>${modeIcon} ${record.description}</td>
                        <td style="text-align: center;">
                            <button class="delete-btn" onclick="deleteRecord(${record.id})">✕</button>
                        </td>
                    </tr>
                `;
            });

            tbody.innerHTML = html;
        }

        // ========== EXPORTAR TXT ==========
        function exportTXT() {
            if (records.length === 0) {
                showStatus("No hi ha actuacions guardades", "error");
                return;
            }

            const showTime = document.getElementById('showTimeInExport').checked;

            let txt = "";
            txt += "===============================\n";
            txt += "BITÀCOLA DE SERVEI\n";
            txt += "===============================\n\n";

            records.forEach((record, index) => {
                txt += `ACTUACIÓ ${records.length - index}\n`;
                txt += "-------------------------------\n";

                if (showTime) {
                    txt += `Hora: ${record.time}\n`;
                }

                txt += `Tipus: ${record.mode === "informe" ? "Informe tipificat" : "Parte diari"}\n\n`;
                txt += `${record.description}\n\n`;
            });

            navigator.clipboard.writeText(txt)
                .then(() => {
                    showStatus("Bitàcola copiada en format TXT", "success");
                })
                .catch(() => {
                    showStatus("Error copiant al portapapeles", "error");
                });
        }

        // ========== LIMPIAR FORMULARIO ==========
        function clearAll() {
            document.getElementById('textOriginal').value = '';
            document.getElementById('textTechnical').value = '';
            document.getElementById('technicalGroup').style.display = 'none';
            document.getElementById('addBtnGroup').style.display = 'none';
            document.getElementById('finalBtnGroup').style.display = 'none';

            // Resetear panel DB
            const panel = document.getElementById("panelDB");
            panel.innerHTML = "<p style='color:#999; font-style:italic;'>Processa un text primer per veure coincidències amb la base de dades.</p>";

            // Volver a tab REDACTOR
            tabRedactor.click();
        }

        // ========== MOSTRAR MENSAJES ==========
        function showStatus(message, type) {
            const status = document.getElementById('status');
            status.textContent = message;
            status.className = `status show ${type}`;
            setTimeout(() => {
                status.classList.remove('show');
            }, 4000);
        }

        function logUsage(action) {
          const payload = {
            user_id: localStorage.getItem("user_id"),
            mode: localStorage.getItem("agent_mode"),
            action: action,
            ts: new Date().toISOString()
          };

          fetch("https://bitacola-backend.onrender.com/api/log", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify(payload)
          }).catch(() => {});
        }

        // ========== RECARGAR AL VOLVER ==========
        window.addEventListener('focus', () => {
            if (db) {
                loadFromDB();
                console.log("🔄 Recàrrega automàtica de DB");
            }
        });

        // ========== INICIALIZACIÓN ==========
        checkBetaAccess();
        initDB();
    </script>
</body>
</html>
