    console.log("📋 Primera persona:", sherlockData.matches.personas[0]);
    console.log("🗃️ db_record:", sherlockData.matches.personas[0].db_record);
}
```

Esto te dirá **exactamente** qué datos hay.

---

### **Opción B: Llamar a explain con formato correcto**

El problema puede ser que el explainer necesita un formato específico.

**Modifica la llamada a `/explain` así:**

```javascript
// BUSCAR (línea ~1134):
const explicacionesResponse = await fetch(
    "https://sherlock-backend-flwb.onrender.com/api/v1/explain",
    {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
            matches: sherlockData.matches
        })
    }
);

// REEMPLAZAR POR:
// Filtrar solo matches con db_record válido
const matchesConDatos = {
    vehiculos: sherlockData.matches.vehiculos.filter(v => v.db_record !== null),
    personas: sherlockData.matches.personas.filter(p => p.db_record !== null),
    ubicaciones: sherlockData.matches.ubicaciones.filter(u => u.db_record !== null)
};

console.log("🔍 Matches con datos:", matchesConDatos);

const explicacionesResponse = await fetch(
    "https://sherlock-backend-flwb.onrender.com/api/v1/explain",
    {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
            matches: matchesConDatos
        })
    }
);
```

---

## 🧪 TEST INMEDIATO

Prueba esto **directamente en la consola** (F12):

```javascript
// Test manual del explainer
const testMatches = {
  vehiculos: [],
  personas: [{
    entidad_original: {
      nombre: "Luz Estrella",
      apellidos: "Gangas",
      dni: ""
    },
    match_type: "PARCIAL",
    confidence: 0.94,
    db_record: {
      dni: "X6590304E",
      nombre: "Luz Estrella",
