async function translateText() {
    const originalText = document.getElementById('textOriginal').value.trim();

    if (!originalText) {
        showStatus('⚠️ Escriu o dicta alguna cosa primer', 'error');
        return;
    }

    document.getElementById('loader').classList.add('show');
    document.getElementById('translateBtn').disabled = true;
    showStatus('🤖 Traduint a llenguatge tècnic...', 'info');

    try {
        // Llamar a TU backend (CAMBIA LA URL)
        const response = await fetch('https://TU-BACKEND.onrender.com/api/translate', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json'
            },
            body: JSON.stringify({
                text: originalText
            })
        });

        const data = await response.json();

        if (data.success) {
            const now = new Date();
            const hora = now.toLocaleTimeString('ca-ES', { hour: '2-digit', minute: '2-digit' });
            const textWithTime = data.translation.replace('[HORA]', hora);

            document.getElementById('textTechnical').value = textWithTime;
            document.getElementById('technicalGroup').style.display = 'block';
            document.getElementById('addBtnGroup').style.display = 'grid';

            showStatus('✅ Traducció completada!', 'success');
        } else {
            throw new Error('Error en traducció');
        }
    } catch (error) {
        console.error('Error:', error);
        showStatus('❌ Error de traducció. Prova amb el text original.', 'error');

        // Fallback: usar texto original
        document.getElementById('textTechnical').value = originalText;
        document.getElementById('technicalGroup').style.display = 'block';
        document.getElementById('addBtnGroup').style.display = 'grid';
    } finally {
        document.getElementById('loader').classList.remove('show');
        document.getElementById('translateBtn').disabled = false;
    }
}
```

