#### **PASO 2: Función de Búsqueda Inteligente**

**En `server.js`:**

```javascript
const fs = require('fs').promises;
const path = require('path');

// Cargar bases de conocimiento al iniciar
let knowledgeBase = {};

async function loadKnowledgeBase() {
    const kbPath = path.join(__dirname, 'knowledge-base');
    const files = await fs.readdir(kbPath);

    for (const file of files) {
        if (file.endsWith('.json')) {
            const content = await fs.readFile(path.join(kbPath, file), 'utf8');
            const data = JSON.parse(content);
            knowledgeBase = { ...knowledgeBase, ...data };
        }
    }

    console.log('📚 Base conocimiento cargada');
}

// Llamar al iniciar servidor
loadKnowledgeBase();

// Búsqueda simple por keywords
function buscarArticulosRelevantes(textoUsuario) {
    const keywords = textoUsuario.toLowerCase();
    const articulos = [];

    for (const seccion in knowledgeBase) {
        for (const articulo of knowledgeBase[seccion]) {
            // Si alguna keyword coincide
            if (articulo.keywords.some(kw => keywords.includes(kw))) {
                articulos.push(articulo);
            }
        }
    }

    return articulos.slice(0, 3); // Máximo 3 artículos más relevantes
}
```

